/* Synthetic study 11 lists. No Reddit, native storage or account writes. */
(function(){
'use strict';
const types={subreddits:'Subreddits',users:'Users',owned:'Your multireddits',followed:'Users’ multireddits'};
const actions={subreddits:'Go to subreddit',users:'Add user',owned:'Create multireddit',followed:'Add user’s multireddits'};
const favoriteIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2 15.1 8.3 22 9.3 17 14.2 18.2 21 12 17.8 5.8 21 7 14.2 2 9.3 8.9 8.3Z"/></svg>';
const rows=(names,type,favorites=[])=>names.map((name,index)=>({id:type+':'+name,name,type,favorite:favorites.includes(name),meta:type==='subreddits'?'r/'+name:type==='users'?'u/'+name:type==='owned'?(index%2?'Private':'Public')+' · '+(index+4)+' subreddits':'u/'+(index%2?'trailnotes':'repairfirst')+' · '+(index+6)+' subreddits'}));
const data={
 weekendreader:{subreddits:rows(['AskReddit','BuyItForLife','CampingandHiking','EarthPorn','gardening','hiking','mildlyinteresting','Outdoors','photography','woodworking'],'subreddits',['hiking','EarthPorn']),users:rows(['mapandcompass','ridgewalker','trailnotes'],'users',['ridgewalker']),owned:rows(['Everyday repairs','Photography','Weekend reads'],'owned',['Weekend reads']),followed:rows(['On the trail','Repair and reuse'],'followed',['On the trail'])},
 guest:{subreddits:rows(['gardening','hiking','woodworking'],'subreddits',['hiking']),users:rows(['trailnotes'],'users'),owned:rows(['Local weekend trails'],'owned'),followed:rows(['On the trail'],'followed')}
};
let readContext,onRoute,stateByAccount={},route='subscriptions',rowReturn=null;
const B=id=>document.getElementById(id),escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function context(){return readContext()}
function state(){const key=context().account;return stateByAccount[key]||(stateByAccount[key]={type:'subreddits',query:'',prefix:false,fixture:'ready',offset:0,message:''})}
function typeOptions(){return Object.entries(types).map(([key,label])=>`<option value="${key}" ${state().type===key?'selected':''}>${label}</option>`).join('')}
function row(item){return `<div class="browse-row"><button type="button" class="browse-open" data-browse-open="${escape(item.id)}"><span class="browse-avatar" aria-hidden="true">${item.type==='subreddits'?'r/':item.type==='users'?'u/':'m/'}</span><span class="browse-copy"><strong>${escape(item.name)}</strong><small>${escape(item.meta)}</small></span></button><button type="button" class="browse-star" data-browse-star="${escape(item.id)}" aria-pressed="${item.favorite}" aria-label="${item.favorite?'Remove':'Add'} ${escape(item.name)} ${item.favorite?'from':'to'} favorites">${favoriteIcon}</button></div>`}
function group(title,items){return items.length?`<section class="browse-group" aria-label="${title}"><h3>${title}</h3>${items.map(row).join('')}</section>`:''}
function listMarkup(){const s=state(),items=data[context().account][s.type].filter(item=>s.prefix?item.name.toLowerCase().startsWith(s.query.toLowerCase()):item.name.toLowerCase().includes(s.query.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));
 if(s.fixture==='loading')return '<p role="status">Loading subscriptions…</p>'+Array.from({length:5},()=>'<div class="browse-placeholder" aria-hidden="true"></div>').join('');
 if(s.fixture==='empty')return '<div class="browse-empty"><strong>Your list starts here.</strong><p>Nothing in this category yet. Use the add action above.</p></div>';
 if(!items.length)return '<div class="browse-empty"><strong>No matches in this list.</strong><p>Try a shorter filter or another category.</p><button type="button" data-browse-clear>Clear filter</button></div>';
 return (s.fixture==='error'?'<p class="browse-feedback" role="status">Couldn’t refresh. Your existing list is still available. <button type="button" data-browse-retry>Retry</button></p>':'')+group('Favorites',items.filter(item=>item.favorite))+group(s.type==='owned'&&context().account==='guest'?'Local multireddits':types[s.type],items.filter(item=>!item.favorite));
}
function updateList(){B('browse-list').innerHTML=listMarkup();B('browse-feedback').textContent=state().message;if(B('browse-fixture'))B('browse-fixture').value=state().fixture}
function render(next=route){route=next;rowReturn=null;const s=state();if(next==='multireddits'&&!['owned','followed'].includes(s.type))s.type='owned';
 return `<div class="browse-controls"><label>List<select id="browse-type">${typeOptions()}</select></label><button type="button" class="browse-add" data-browse-add aria-label="${actions[s.type]}">+</button></div><div class="browse-filter"><input id="browse-filter" type="search" aria-label="Filter this list" placeholder="Filter this list" value="${escape(s.query)}"><button type="button" data-browse-clear aria-label="Clear list filter">×</button></div><details class="browse-options"><summary>List options</summary><label><input id="browse-prefix" type="checkbox" ${s.prefix?'checked':''}>Match from the start</label><button type="button" data-browse-refresh ${context().account==='guest'?'disabled':''}>Refresh subscriptions</button>${context().account==='guest'?'<p>Guest lists are stored locally.</p>':''}</details><p class="browse-caption">${context().account==='guest'?'Guest · local lists':'weekendreader · '+(s.type==='followed'?'Saved from other users':'Account list')}</p><p id="browse-feedback" class="browse-feedback" role="status">${escape(s.message)}</p><div id="browse-list">${listMarkup()}</div>`
}
function remount(){const y=state().offset;B('destination').innerHTML=render();B('destination').scrollTop=y}
function item(id){return Object.values(data[context().account]).flat().find(row=>row.id===id)}
function showRow(id){const selected=item(id);rowReturn={offset:B('destination').scrollTop,id};B('destination').innerHTML=`<button type="button" class="browse-back" data-browse-back>← Back to list</button><h3 tabindex="-1">${escape(selected.type==='subreddits'?'r/'+selected.name:selected.name)}</h3><p class="result-meta">${escape(selected.meta)} · ${context().account==='guest'?'Guest':'weekendreader'}</p><p>Destination preview. The native app opens its existing ${selected.type==='subreddits'?'subreddit':selected.type==='users'?'user profile':'multireddit'} route with this account.</p>${selected.name==='hiking'?'<p><a href="subreddit.html?rev=12">Open accepted subreddit header study →</a></p>':''}<p>The full list design is under review; post/profile and multireddit detail content is outside this step.</p>`;B('destination').scrollTop=0;B('destination').querySelector('h3').focus({preventScroll:true})}
function showAction(){const s=state(),dialog=document.createElement('dialog');dialog.className='browse-dialog';dialog.setAttribute('aria-labelledby','browse-action-title');dialog.innerHTML=`<h2 id="browse-action-title">${actions[s.type]}</h2><p>This opens Continuum’s existing ${s.type==='owned'?'multireddit editor':s.type==='followed'?'user multireddit chooser':s.type==='users'?'add-user options':'subreddit entry'} route. Its form will be reviewed in the create/act group.</p><p>No account changes occur in this preview.</p><button type="button" data-browse-close>Close</button>`;B('nav-phone').append(dialog);dialog.addEventListener('close',()=>{dialog.remove();B('destination').querySelector('[data-browse-add]')?.focus({preventScroll:true})});dialog.showModal()}
function initialize(getContext,go){readContext=getContext;onRoute=go;
 document.addEventListener('scroll',event=>{if(event.target.id==='destination'&&B('browse-list'))state().offset=event.target.scrollTop},{capture:true,passive:true});
 document.addEventListener('input',event=>{if(event.target.id==='browse-filter'){state().query=event.target.value;state().message='';updateList()}});
 document.addEventListener('change',event=>{if(event.target.id==='browse-type'){state().type=event.target.value;state().offset=0;state().message='';if(route==='multireddits'&&['subreddits','users'].includes(state().type))onRoute('subscriptions');else remount();B('browse-type').focus({preventScroll:true});B('destination').querySelector('[data-browse-add]').setAttribute('aria-label',actions[state().type])}if(event.target.id==='browse-prefix'){state().prefix=event.target.checked;updateList()}});
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;
  if(button.hasAttribute('data-browse-clear')){state().query='';state().message='';B('browse-filter').value='';updateList();B('browse-filter').focus({preventScroll:true})}
  if(button.dataset.browseStar){const selected=item(button.dataset.browseStar);if(state().fixture==='favorite-error'){state().message='Couldn’t change favorite. Previous state kept.';updateList()}else{selected.favorite=!selected.favorite;state().message=selected.name+(selected.favorite?' added to':' removed from')+' favorites.';updateList()}B('browse-list').querySelector(`[data-browse-star="${CSS.escape(selected.id)}"]`)?.focus({preventScroll:true})}
  if(button.dataset.browseOpen)showRow(button.dataset.browseOpen);
  if(button.hasAttribute('data-browse-back')){const back=rowReturn;B('destination').innerHTML=render();B('destination').scrollTop=back.offset;B('destination').querySelector(`[data-browse-open="${CSS.escape(back.id)}"]`)?.focus({preventScroll:true})}
  if(button.hasAttribute('data-browse-add'))showAction();
  if(button.hasAttribute('data-browse-close'))button.closest('dialog').close();
  if(button.hasAttribute('data-browse-retry')||button.hasAttribute('data-browse-refresh')){state().fixture='ready';state().message='Subscriptions refreshed · fixture.';updateList()}
 });
 const study=new URLSearchParams(location.search).get('study')==='11';if(study){document.title='Relaxe · Subscriptions study 11';document.querySelector('.topline>span').textContent='SUBSCRIPTIONS / 11';document.querySelector('.badge').textContent='Single selector selected · tighter rows · revision 14';document.querySelector('.intro h1').innerHTML='Your lists.<br>Within reach.';document.querySelector('.intro>p').textContent='A compact list selector, a filter for your subscriptions, and favorite stars. The same account drawer, bottom navigation and Search stay available.';
 document.querySelector('.nav-notes').innerHTML='<p class="eyebrow">SUBSCRIPTIONS / 11 · PROPOSAL</p><h2>A familiar list, refined.</h2><ol><li>Choose Subreddits, Users, Your multireddits or Users’ multireddits.</li><li>Filter only the current list. Bottom Search still searches Reddit.</li><li>Tap a star. Favorites sit first; every row remains accessible.</li><li>Open a row and return: filter and scroll position stay.</li><li>Try Guest, large text and the failure fixtures above.</li></ol><h3>Selected</h3><p>Single list selector and visible favorite stars, matching your choices. The rows are tighter while retaining their labels and touch targets.</p><h3>Density reference</h3><p>Tighter rows are the selected direction. Final spacing must be judged in the Android app with its fonts, scaling, touch targets and insets; browser pixels do not establish native density.</p><h3>Preserved</h3><p>Account-specific lists, Guest’s local data, alphabetical ordering, favorites, prefix filtering and existing destination/add routes. Add/edit forms are reviewed later.</p><p><a href="../../DESIGN.md">Decisions and native verification limits</a></p>';
 const fixtures=document.createElement('div');fixtures.className='controls browse-fixture-controls';fixtures.innerHTML='<label>List account<select id="browse-account"><option value="weekendreader">weekendreader · fixture</option><option value="guest">Guest · local fixture</option></select></label><label>List fixture<select id="browse-fixture"><option value="ready">Normal</option><option value="loading">Loading</option><option value="error">Refresh failure · keep list</option><option value="empty">Empty category</option><option value="favorite-error">Favorite failure</option></select></label><label>Direction<select id="browse-direction"><option value="ltr">Left to right</option><option value="rtl">Right to left</option></select></label>';document.querySelector('.bench .small').before(fixtures);
 B('browse-account').addEventListener('change',event=>{onRoute('account',event.target.value)});B('browse-fixture').addEventListener('change',event=>{state().fixture=event.target.value;state().message='';onRoute(route)});B('browse-direction').addEventListener('change',event=>B('nav-phone').dir=event.target.value);
 }
}
window.RelaxeBrowse={initialize,render,state};
})();
